#include <stdio.h>
int main(void)  {
    // h、m 描述今天时刻，d 是非负延迟；一天固定 1440 分钟。
    long long h, m, d;
    scanf("%lld%lld%lld", &h, &m, &d);
    // 先把全部量统一为分钟，进位才能由除法和取余自动完成。
    long long total = h * 60 + m + d;
    // 依次输出完整天数、当天小时、剩余分钟，不需要补前导零。
    printf("%lld %lld %lld\n", total / 1440, total % 1440 / 60, total % 60);
    return 0;
}

